\title{The Projective Galois Structure of the Riccati Equation\\
and the Kovacic Obstruction for EML Ordinary Differential Equations}
\author{Aristotle}
\date{2026-06-28}

\begin{document}
\maketitle

\begin{abstract}
We develop the differential-Galois theory of ordinary differential equations
whose coefficients are \emph{exponential--logarithmic} (EML) functions, working
entirely within an abstract differential field $K$ with derivation
$x \mapsto x'$. The central object is the \textbf{Riccati equation}
$v' + v^2 + p\,v + q = 0$, satisfied by the logarithmic derivative $v = y'/y$ of
a solution of the second-order linear equation $y'' + p\,y' + q\,y = 0$. Our main
structural result is that the differential Galois group of the Riccati equation
is \textbf{projective}: it embeds in $\PGL_2$ of the field of constants. We prove
this in basis-free form by exhibiting the projective invariant---the
\textbf{cross-ratio} of four solutions---as a constant of the differential field.
The proof rests on a \emph{difference law}: the difference of two Riccati
solutions satisfies a first-order linear equation, combined with the homomorphism
property of the logarithmic derivative. We connect this to the \textbf{Kovacic
decision procedure}: the gauge reducing a general second-order EML equation to
normal Riccati form, the clearing of denominators translating rational
solvability into a polynomial identity, and a degree-parity obstruction proving
that \textbf{Airy's equation} $y'' = x\,y$ has no elementary (EML) solution. The
parity criterion is sharp: every odd-degree coefficient $x^{2k+1}$ is obstructed,
while $x^2+1$ admits the explicit rational Riccati solution $v = x$
(corresponding to $y = e^{x^2/2}$). Symmetry results hold over an arbitrary
differential field with no characteristic or algebraic-closure hypotheses;
obstruction results live in $\R[X]$.
\end{abstract}

\section{Introduction}

\subsection{Differential Galois theory}
Classical Galois theory attaches to a polynomial a finite group of symmetries and
reads off solvability by radicals from the group's structure. Differential Galois
theory (Picard--Vessiot theory) performs the analogous construction for linear
ordinary differential equations: it attaches a linear-algebraic group acting on
the solution space, and the question of elementary (Liouvillian) solvability
becomes a question about that group. The base field is the \emph{field of
constants}, the elements annihilated by the derivation.

\subsection{EML equations}
By an \textbf{EML function} we informally mean a function built from the
exponential, the logarithm, polynomials, and field operations. The organizing
slogan is: \emph{the differential Galois group of an EML equation is an EML
group.} For the first-order linear equation $y' = a\,y$ this is the multiplicative
group of nonzero constants $\Gm$. Our contribution is the nonlinear analogue for
the Riccati equation, whose group is \textbf{projective}.

\subsection{The differential-field formalism}
A \textbf{differential field} is a field $K$ with a derivation $\partial$, written
$x' := \partial x$, satisfying additivity and the Leibniz rule
$(xy)' = x'y + xy'$. All identities below are algebraic consequences of these
axioms.

\begin{definition}[Constants]
The \emph{field of constants} of $K$ is $\C = \{ x \in K : x' = 0 \}$. It is a
subfield: closed under addition, multiplication, and inverse, and contains
$0,1$. (Formalized as \texttt{constantsSubfield}, with
\texttt{mem\_constantsSubfield}: $x \in \C \iff x' = 0$.)
\end{definition}

\section{The logarithmic derivative as a homomorphism}

The engine of the theory is the \textbf{logarithmic derivative}
$L : K^\times \to (K,+)$, $L(y) = y'/y$.

\begin{lemma}[Homomorphism property, \texttt{logDeriv\_mul}]
For nonzero $y,z$, $\dfrac{(yz)'}{yz} = \dfrac{y'}{y} + \dfrac{z'}{z}.$
\end{lemma}
\begin{proof}
Apply Leibniz: $(yz)' = y'z + yz'$; divide by $yz$ and simplify.
\end{proof}

This is the abstract $\log(yz) = \log y + \log z$. Companions: $L(y/z)=L(y)-L(z)$
(\texttt{logDeriv\_div}), $L(y^{-1})=-L(y)$ (\texttt{logDeriv\_inv}),
$L(y^n)=n\,L(y)$ for $n\in\Z$ (\texttt{logDeriv\_zpow}). The kernel of $L$ is
exactly $\C$.

\begin{lemma}[Superposition, \texttt{firstOrder\_mul}]
If $y' = a\,y$ and $z' = b\,z$, then $(yz)' = (a+b)\,(yz)$.
\end{lemma}
\begin{proof}
$(yz)' = y'z + yz' = ayz + byz = (a+b)yz$.
\end{proof}

\begin{lemma}[Quotient solution, \texttt{firstOrder\_div}]
If $y' = a\,y$, $z' = b\,z$, and $z \neq 0$, then $(y/z)' = (a-b)\,(y/z)$.
\end{lemma}

A finite version (\texttt{firstOrder\_prod}): for $(y_i)' = a_i y_i$,
$\bigl(\prod_i y_i\bigr)' = \bigl(\sum_i a_i\bigr)\prod_i y_i$.

\section{The first-order Galois group is $\Gm(\C)$}

\begin{theorem}[Constant ratio, \texttt{solution\_ratio\_isConstant}]
If $y_1' = a y_1$, $y_2' = a y_2$ and $y_1 \neq 0$, then $(y_2/y_1)' = 0$.
\end{theorem}
\begin{proof}
The numerator of $(y_2/y_1)'$ is $y_2' y_1 - y_2 y_1' = a y_2 y_1 - y_2 a y_1 = 0$.
\end{proof}

\begin{theorem}[Galois action is scaling, \texttt{galois\_action\_is\_mul\_constant}]
Any two nonzero solutions of $y' = a y$ differ by a nonzero constant: there is $c$
with $c \neq 0$, $c' = 0$, $y_2 = c y_1$.
\end{theorem}
\begin{proof}
Take $c = y_2/y_1$: nonzero, constant by the previous theorem, and $y_2 = c y_1$.
\end{proof}

\begin{theorem}[Torsor, \texttt{galois\_torsor}]
For fixed nonzero $y_1$, an element $y_2$ is a nonzero solution iff $y_2 = c y_1$
for a nonzero constant $c$.
\end{theorem}

Thus the Galois group of $y' = a y$ acts by $\Gm(\C)$, the prototypical EML group.

\section{The projective Galois group of the Riccati equation}

\begin{definition}[Riccati equation]
For $p,q \in K$, the \emph{Riccati equation} is $v' + v^2 + p\,v + q = 0$.
\end{definition}

\begin{proposition}[Full Riccati transform, \texttt{riccati\_full\_of\_second\_order}]
If $y \neq 0$ solves $y'' + p y' + q y = 0$, then $v = y'/y$ solves
$v' + v^2 + p v + q = 0$.
\end{proposition}
\begin{proof}[Proof sketch]
Use $(y'/y)' + (y'/y)^2 = y''/y$ and substitute $y'' = -p y' - q y$.
\end{proof}

\begin{theorem}[Difference law, \texttt{riccati\_diff}]
If $v_1,v_2$ solve $v' + v^2 + p v + q = 0$, then
\[ (v_1 - v_2)' = -(v_1 + v_2 + p)\,(v_1 - v_2). \]
\end{theorem}
\begin{proof}
Subtracting the equations,
$(v_1-v_2)' = -(v_1^2 - v_2^2) - p(v_1-v_2) = -[(v_1+v_2)+p](v_1-v_2)$,
using $v_1^2 - v_2^2 = (v_1+v_2)(v_1-v_2)$ and cancellation of $q$.
\end{proof}

\begin{definition}[Cross-ratio, \texttt{crossRatio}]
For $v_1,v_2,v_3,v_4 \in K$,
\[ [v_1,v_2;v_3,v_4] = \frac{(v_1-v_3)(v_2-v_4)}{(v_1-v_4)(v_2-v_3)}. \]
\end{definition}

\begin{theorem}[Invariance, \texttt{riccati\_crossRatio\_isConstant}]
Let $v_1,v_2,v_3,v_4$ solve $v'+v^2+pv+q=0$, with $v_1 \neq v_4$, $v_2 \neq v_3$.
Then $\bigl([v_1,v_2;v_3,v_4]\bigr)' = 0$.
\end{theorem}
\begin{proof}
By the difference law each factor is a first-order solution. With
$N = (v_1-v_3)(v_2-v_4)$, $D=(v_1-v_4)(v_2-v_3)$, superposition gives
$N' = \kappa_N N$, $D' = \kappa_D D$ where
\[
\kappa_N = -(v_1{+}v_3{+}p) - (v_2{+}v_4{+}p), \quad
\kappa_D = -(v_1{+}v_4{+}p) - (v_2{+}v_3{+}p).
\]
Since $D \neq 0$, the quotient rule yields $(N/D)' = (\kappa_N - \kappa_D)(N/D)$.
But $\kappa_N = \kappa_D = -(v_1{+}v_2{+}v_3{+}v_4{+}2p)$, so $\kappa_N-\kappa_D=0$
and $(N/D)' = 0$.
\end{proof}

\paragraph{Interpretation.} This is the basis-free statement that the
differential Galois group of the Riccati equation is a subgroup of $\PGL_2(\C)$:
its action preserves the cross-ratio, exactly as Möbius maps do. The
cancellation $\kappa_N = \kappa_D$ is the differential-algebraic chain-rule
identity underlying Möbius invariance.

\paragraph{Degeneration chain.} Knowledge of explicit solutions degenerates the
group along
\[ \PGL_2(\C) \supset \Ga \rtimes \Gm \supset \Gm \supset 1, \]
each known solution removing one projective degree of freedom: one solution
linearizes via $v = v_0 + 1/u$, $u' = (2v_0+p)u + 1$; two leave $\Gm$; three fix
the projective coordinate completely. The count of rational solutions
($0,1,2,\infty$) is a complete discrete invariant.

\section{Reduction to normal form: the Riccati gauge}

\begin{theorem}[Riccati gauge, \texttt{riccati\_gauge}]
If $2g = p$ and $v$ solves $v' + v^2 + p v + q = 0$, then $\tilde v = v + g$
solves $\tilde v' + \tilde v^2 = g' + g^2 - q$.
\end{theorem}
\begin{proof}
Expand $(v+g)' + (v+g)^2 - (g'+g^2-q) = (v'+v^2+pv+q) + (2g-p)v$; both terms
vanish. Division-free, valid in any differential field.
\end{proof}

\begin{corollary}[\texttt{riccati\_normalForm\_of\_second\_order}]
A nonzero solution $y$ of $y''+py'+qy=0$, gauged by $g$ with $2g = p$, yields
$\tilde v = y'/y + g$ solving $\tilde v' + \tilde v^2 = g'+g^2-q$, where
$r = g'+g^2-q = q - \tfrac{p^2}{4} - \tfrac{p'}{2}$ for $g = p/2$.
\end{corollary}

\section{The Kovacic obstruction: Airy has no EML solution}

\begin{definition}[\texttt{HasRationalRiccatiSolution}]
$f \in \R[X]$ has a rational Riccati solution if there are $p,q \in \R[X]$ with
$q \neq 0$ and $p'q - pq' + p^2 = f q^2$ (the cleared form of $v' + v^2 = f$,
$v = p/q$).
\end{definition}

\begin{lemma}[Degree bound, \texttt{natDegree\_wronskianLike\_le}]
$\deg(p'q - pq') \le \deg p + \deg q - 1$.
\end{lemma}

\begin{theorem}[Odd-degree obstruction, \texttt{no\_rational\_solves\_riccati\_odd\_deg}]
If $f$ has odd degree, then $p'q - pq' + p^2 = f q^2$ has no solution with
$q \neq 0$.
\end{theorem}
\begin{proof}
The right side has odd degree $\deg f + 2\deg q$. If $\deg p \ge \deg q$, the left
side has degree $2\deg p$ (the $p^2$ term dominates, by the lemma), which is even,
forcing $\deg f$ even---contradiction. If $\deg p < \deg q$, the left side has
degree $\le 2\deg q - 2$, strictly below the right side's $\ge 2\deg q + 1$.
Either way, contradiction. Coprimality is not required.
\end{proof}

\begin{theorem}[Airy, \texttt{no\_rational\_solves\_riccati\_airy}]
There are no $p,q \in \R[X]$ with $q \neq 0$ and $p'q - pq' + p^2 = X q^2$.
\end{theorem}
\begin{proof}
Apply the previous theorem with $f = X$, of degree $1$ (odd).
\end{proof}

Together with the polynomial-level result (\texttt{no\_poly\_solves\_airy}), this
packages as \texttt{airy\_no\_poly\_and\_no\_rational\_riccati}: Airy's equation
$y'' = x y$ has neither a polynomial solution nor a rational Riccati solution---the
first two Kovacic layers certifying no elementary (EML) closed form.

\begin{theorem}[Generalized Airy, \texttt{no\_rational\_riccati\_genAiry}]
For every $k \in \N$, $f = X^{2k+1}$ has no rational Riccati solution.
\end{theorem}

\begin{theorem}[Even-degree solvability, \texttt{riccati\_evenDeg\_solvable}]
$f = X^2 + 1$ has the explicit solution $v = X$ ($p = X$, $q = 1$).
\end{theorem}
\begin{proof}
$p'q - pq' + p^2 = 1 + X^2 = f q^2$. Corresponds to $y'' = (x^2+1)y$, solved by
$y = e^{x^2/2}$.
\end{proof}

\begin{theorem}[Sharpness, \texttt{kovacic\_parity\_decision\_sharp}]
On the family $y'' = f y$, every $X^{2k+1}$ is obstructed while $X^2+1$ is
solvable; the odd-degree hypothesis cannot be dropped.
\end{theorem}

\section{Algorithmic summary}
For $y'' + p y' + q y = 0$:
\begin{enumerate}
\item Gauge to normal form: $2g = p$, $r = g' + g^2 - q$.
\item Test rational solvability: $p_0'q_0 - p_0 q_0' + p_0^2 = r q_0^2$.
\item Parity shortcut: odd $\deg r$ $\Rightarrow$ unsolvable (Airy: $r = x$).
\item Symmetry bookkeeping: cross-ratio constant; solution count
$0,1,2,\infty$ pins the group on $\PGL_2 \supset \Ga\rtimes\Gm \supset \Gm
\supset 1$.
\end{enumerate}

\section{Discussion}
The first-order linear theory gives a $\Gm(\C)$-torsor (a line of solutions); the
nonlinear Riccati equation carries a \emph{projective} line, with group
$\PGL_2(\C)$ and invariant the cross-ratio. The difference law unifies the two:
each $v_i - v_j$ is a rank-one ($\Gm$) object, and the projective combination of
four collapses the additive coefficients to zero. Second-order linear ODEs
pervade physics; the Kovacic algorithm decides closed-form solvability, and Airy
functions---fundamental in optics and quantum mechanics---are provably
non-elementary by a transparent degree-parity count.

\section{Future directions}
The action degenerates along
$\PGL_2(\C) \supset \Ga\rtimes\Gm \supset \Gm \supset 1$. Three conjectures:
(1) effective three-solution Möbius reconstruction giving a bijection
$\{\text{solutions}\} \simeq \C \cup \{\infty\}$; (2) strict, complete
degeneration over an algebraically closed constant field, with solution count
$0,1,2,\infty$ a complete invariant; (3) extension of the odd-degree obstruction
to the full transcendental EML setting.

